import React, { useEffect, useState, useCallback } from "react";
import axios from "axios";
import { FaBookMedical, FaPlusCircle, FaEdit, FaTrash, FaClock } from "react-icons/fa";
import { useNavigate } from "react-router-dom";
import DashboardCard from "./DashboardCard";
import SectionCard from "./SectionCard";
import PageHeader from "./PageHeader";
import AlertBox from "./AlertBox";
import "./dashboard.css";

function TeacherDashboard() {
  const teacherId = localStorage.getItem("user_id");
  const navigate = useNavigate();

  const [formData, setFormData] = useState({
    title: "",
    description: "",
    subject_code: ""
  });

  const [courses, setCourses] = useState([]);
  const [alert, setAlert] = useState(null);
  const [editCourseId, setEditCourseId] = useState(null);

  const fetchCourses = useCallback(async () => {
    try {
      const response = await axios.get("http://127.0.0.1:8000/courses");
      const allCourses = response.data.courses || [];
      const myCourses = allCourses.filter(
        (course) => String(course.teacher_id) === String(teacherId)
      );
      setCourses(myCourses);
    } catch (error) {
      console.error(error);
    }
  }, [teacherId]);

  useEffect(() => {
    fetchCourses();
  }, [fetchCourses]);

  const handleChange = (e) => {
    setFormData({
      ...formData,
      [e.target.name]: e.target.value
    });
  };

  const handleEdit = (course) => {
    setFormData({
      title: course.title,
      description: course.description,
      subject_code: course.subject_code
    });
    setEditCourseId(course.id);
  };

  const handleDelete = async (courseId) => {
    try {
      const res = await axios.delete(`http://127.0.0.1:8000/delete-course/${courseId}`);
      setAlert({ message: res.data.message, type: "success" });
      fetchCourses();
    } catch (error) {
      console.error(error);
      setAlert({ message: "Course deletion failed", type: "error" });
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    try {
      const payload = {
        ...formData,
        teacher_id: parseInt(teacherId)
      };

      let res;
      if (editCourseId) {
        res = await axios.put(`http://127.0.0.1:8000/update-course/${editCourseId}`, payload);
      } else {
        res = await axios.post("http://127.0.0.1:8000/create-course", payload);
      }

      setAlert({ message: res.data.message, type: "success" });
      setFormData({ title: "", description: "", subject_code: "" });
      setEditCourseId(null);
      fetchCourses();
    } catch (error) {
      console.error(error);
      setAlert({ message: "Course save failed", type: "error" });
    }
  };

  const recentCourses = [...courses].slice(0, 3);

  return (
    <div>
      {alert && <AlertBox message={alert.message} type={alert.type} onClose={() => setAlert(null)} />}

      <PageHeader
        title="Teacher Dashboard"
        subtitle="Create and manage your most recent courses."
        action={
          <button className="btn btn-primary" onClick={() => navigate("/courses")}>
            View All Courses
          </button>
        }
      />

      <div className="grid-3" style={{ marginBottom: 18 }}>
        <DashboardCard icon={<FaBookMedical />} label="Total Courses" value={courses.length} />
        <DashboardCard icon={<FaClock />} label="Recent Courses" value={recentCourses.length} />
        <DashboardCard icon={<FaPlusCircle />} label="Active Role" value="Teacher" badge="Live" />
      </div>

      <div className="grid-2">
        <SectionCard title={editCourseId ? "Edit Course" : "Add New Course"}>
          <form onSubmit={handleSubmit}>
            <input
              className="input"
              type="text"
              name="title"
              placeholder="Course Title"
              value={formData.title}
              onChange={handleChange}
            />
            <input
              className="input"
              type="text"
              name="description"
              placeholder="Course Description"
              value={formData.description}
              onChange={handleChange}
            />
            <input
              className="input"
              type="text"
              name="subject_code"
              placeholder="Subject Code"
              value={formData.subject_code}
              onChange={handleChange}
            />
            <button className="btn btn-primary" type="submit">
              {editCourseId ? "Update Course" : "Add Course"}
            </button>
          </form>
        </SectionCard>

        <SectionCard title="Recent Added Courses">
          {recentCourses.length === 0 ? (
            <p>No recent courses found.</p>
          ) : (
            recentCourses.map((course) => (
              <div className="list-card" key={course.id}>
                <h4 style={{ margin: 0 }}>{course.title}</h4>
                <div className="meta">{course.description}</div>
                <div className="meta">Subject Code: {course.subject_code}</div>
                <div className="meta">Created By: {course.created_by || "You"}</div>
                <div className="meta">
                  Created At: {course.created_at ? new Date(course.created_at).toLocaleString() : "N/A"}
                </div>
                <div className="btn-row" style={{ marginTop: 12 }}>
                  <button className="btn btn-info" onClick={() => handleEdit(course)}>
                    <FaEdit style={{ marginRight: 6 }} />
                    Edit
                  </button>
                  <button className="btn btn-danger" onClick={() => handleDelete(course.id)}>
                    <FaTrash style={{ marginRight: 6 }} />
                    Delete
                  </button>
                </div>
              </div>
            ))
          )}
        </SectionCard>
      </div>
    </div>
  );
}

export default TeacherDashboard;
